-- --------------------------------------------------------------------
-- Table & Indexes for `sectors`
-- --------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.sectors (
    code VARCHAR(50) PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    description TEXT,
    is_cbam BOOLEAN DEFAULT TRUE,
    scope_rule VARCHAR(50) DEFAULT 'SCOPE_1_2'
);


-- --------------------------------------------------------------------
-- Table & Indexes for `facilities`
-- --------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.facilities (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    sector_code VARCHAR(50) NOT NULL REFERENCES public.sectors(code) ON UPDATE CASCADE,
    tax_id VARCHAR(50) UNIQUE NOT NULL,
    address VARCHAR(255) NOT NULL,
    province VARCHAR(100) NOT NULL,
    contact_person VARCHAR(100),
    phone VARCHAR(50),
    email VARCHAR(150),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_facilities_sector ON public.facilities(sector_code);

SELECT setval(pg_get_serial_sequence('public.facilities', 'id'), COALESCE((SELECT MAX(id) FROM public.facilities), 1), true);

-- --------------------------------------------------------------------
-- Table & Indexes for `users`
-- --------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.users (
    id SERIAL PRIMARY KEY,
    facility_id INT REFERENCES public.facilities(id) ON DELETE SET NULL ON UPDATE CASCADE,
    username VARCHAR(100) UNIQUE NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(150) NOT NULL,
    role VARCHAR(50) NOT NULL CHECK (role IN ('admin', 'manager', 'accountant', 'engineer')),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_users_facility ON public.users(facility_id);

SELECT setval(pg_get_serial_sequence('public.users', 'id'), COALESCE((SELECT MAX(id) FROM public.users), 1), true);

-- --------------------------------------------------------------------
-- Table & Indexes for `user_roles`
-- Cho phép 1 user có nhiều role, gán quyền theo từng facility cụ thể
-- Cột `role` trong bảng users vẫn giữ là "primary role" mặc định
-- --------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_roles (
    id SERIAL PRIMARY KEY,
    user_id INT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE ON UPDATE CASCADE,
    facility_id INT REFERENCES public.facilities(id) ON DELETE CASCADE ON UPDATE CASCADE,
    role VARCHAR(50) NOT NULL CHECK (role IN ('admin', 'manager', 'accountant', 'engineer')),
    granted_by INT REFERENCES public.users(id) ON DELETE SET NULL,
    granted_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_user_facility_role UNIQUE (user_id, facility_id, role)
);
CREATE INDEX IF NOT EXISTS idx_user_roles_user ON public.user_roles(user_id);
CREATE INDEX IF NOT EXISTS idx_user_roles_facility ON public.user_roles(facility_id);

-- Seed: Ánh xạ các user mẫu sang bảng user_roles (khớp với dữ liệu users)
-- User 1 (ketoan) -> accountant tại facility 1
-- User 2 (kythuat) -> engineer tại facility 1
-- User 3 (giamdoc) -> manager tại facility 1, có thêm quyền xem accountant
-- User 4 (admin) -> admin toàn hệ thống (facility_id NULL = không giới hạn facility)
SELECT setval(pg_get_serial_sequence('public.user_roles', 'id'), COALESCE((SELECT MAX(id) FROM public.user_roles), 1), true);

