    gwp_value DOUBLE PRECISION DEFAULT 1.0,
    source VARCHAR(255) NOT NULL,
    note TEXT
);
CREATE INDEX IF NOT EXISTS idx_ef_category ON public.emission_factors(category);

SELECT setval(pg_get_serial_sequence('public.emission_factors', 'id'), COALESCE((SELECT MAX(id) FROM public.emission_factors), 1), true);

